// AccountServiceHandler is an implementation of the hawkr.account.AccountService service.
type AccountServiceHandler interface {
	// Google OAuth 登入/註冊
	GoogleOAuth(context.Context, *connect.Request[account.GoogleOAuthRequest]) (*connect.Response[account.AuthResponse], error)
	AppleOAuth(context.Context, *connect.Request[account.AppleOAuthRequest]) (*connect.Response[account.AuthResponse], error)
	// 驗證用戶 Token
	ValidateUser(context.Context, *connect.Request[account.ValidateUserRequest]) (*connect.Response[account.ValidateUserResponse], error)
	// 手機驗證
	VerifyPhone(context.Context, *connect.Request[account.VerifyPhoneRequest]) (*connect.Response[account.VerifyPhoneResponse], error)
	// 發送手機 OTP 簡訊（後端經三竹發送，51 號設計書）
	SendOtp(context.Context, *connect.Request[account.SendOtpRequest]) (*connect.Response[account.SendOtpResponse], error)
	// Token 刷新
	RefreshToken(context.Context, *connect.Request[account.RefreshTokenRequest]) (*connect.Response[account.RefreshTokenResponse], error)
	// 獲取帳號信息
	GetAccountInfo(context.Context, *connect.Request[account.GetAccountInfoRequest]) (*connect.Response[account.AccountInfoResponse], error)
	// 批量獲取帳號信息
	GetAccountInfoBatch(context.Context, *connect.Request[account.GetAccountInfoBatchRequest]) (*connect.Response[account.AccountInfoBatchResponse], error)
	// 檢查手機號是否可用
	CheckPhone(context.Context, *connect.Request[account.CheckPhoneRequest]) (*connect.Response[account.CheckPhoneResponse], error)
	// 依手機號查詢帳號資訊
	GetAccountByPhone(context.Context, *connect.Request[account.GetAccountByPhoneRequest]) (*connect.Response[account.AccountInfoResponse], error)
	// 綁定賣家
	BindSeller(context.Context, *connect.Request[account.BindSellerRequest]) (*connect.Response[account.BindSellerResponse], error)
	// 綁定買家角色（buyer-service 建立 buyer row 後補 account_type 的 buyer bit）
	BindBuyer(context.Context, *connect.Request[account.BindBuyerRequest]) (*connect.Response[account.BindBuyerResponse], error)
	// 管理員帳號密碼登入
	AdminLogin(context.Context, *connect.Request[account.AdminLoginRequest]) (*connect.Response[account.AdminLoginResponse], error)
	// 管理員 Google SSO 登入（驗 Google idToken + admin_account allowlist）
	AdminGoogleLogin(context.Context, *connect.Request[account.AdminGoogleLoginRequest]) (*connect.Response[account.AdminLoginResponse], error)
	// 停權帳號（審核處置，區別於軟刪除；不動 deleted_at）。寫 accounts.status
	// 與 account:blocked:<id> 兩者——後者是前者的衍生快取，同一個 use case 內寫
	// 完，呼叫端不需要（也不應該）自己碰 Redis。
	SuspendAccount(context.Context, *connect.Request[account.SuspendAccountRequest]) (*connect.Response[account.SuspendAccountResponse], error)
	// 解除停權（#2053）：DEL account:blocked:<id> 後把 status 寫回 active。
	// 順序不可顛倒——先寫 status 會產生「SSOT 說 active、衍生快取說 blocked」的
	// 中間態，帳號各處看起來正常卻每個請求都 401。詳見 17 號設計書
	//「帳號停權與解除停權」。軟刪帳號不可解除（GetByID 的 deleted_at IS NULL
	// 即為該防線：軟刪路徑寫的是同一把 key，放行等於清掉「已刪除」的證據）。
	UnsuspendAccount(context.Context, *connect.Request[account.UnsuspendAccountRequest]) (*connect.Response[account.UnsuspendAccountResponse], error)
	// Admin 會員管理唯讀面（#2053）。以 accounts 為主軸而非 buyers：可施加的
	// 狀態動作全部 key 在 account_id，且 buyers 含大量已軟刪帳號的殘留 stint。
	ListAccountsForAdmin(context.Context, *connect.Request[account.ListAccountsForAdminRequest]) (*connect.Response[account.ListAccountsForAdminResponse], error)
	GetAccountForAdmin(context.Context, *connect.Request[account.GetAccountForAdminRequest]) (*connect.Response[account.GetAccountForAdminResponse], error)
	// RemoveRole removes a single role from an account. If no roles remain,
	// the account is fully soft-deleted (Apple revoke + Redis blacklist + MQ).
	RemoveRole(context.Context, *connect.Request[account.RemoveRoleRequest]) (*connect.Response[account.RemoveRoleResponse], error)
	// LinkConfirm consumes a tempBindToken (issued by Google/Apple OAuth on
	// 1304 email collision) and atomically links the new (provider, sub_id)
	// to the existing target account. Returns AuthData on success.
	LinkConfirm(context.Context, *connect.Request[account.LinkConfirmRequest]) (*connect.Response[account.LinkConfirmResponse], error)
	// ListAuthProviders lists all auth_provider links bound to the calling
	// account.
	ListAuthProviders(context.Context, *connect.Request[account.ListAuthProvidersRequest]) (*connect.Response[account.ListAuthProvidersResponse], error)
	// BindAuthProvider binds a new (provider, sub_id) to the calling account
	// — used by "從個人中心新增登入方式" flow. The server performs token
	// verification before persisting the link.
	BindAuthProvider(context.Context, *connect.Request[account.BindAuthProviderRequest]) (*connect.Response[account.BindAuthProviderResponse], error)
	// UnbindAuthProvider removes an auth_provider link from the calling
	// account. For Apple links, also enqueues an apple_revoke_outbox row.
	UnbindAuthProvider(context.Context, *connect.Request[account.UnbindAuthProviderRequest]) (*connect.Response[account.UnbindAuthProviderResponse], error)
	// Web session 的持久層（issue #1592 建立，#2014 → PR #2022 起升為 SSOT）：
	// `web_sessions` row 是 web session 的唯一真實來源，Redis 只是加速層，因此
	// 每個 Redis miss／error 都會 read-through 打到這組 RPC，不限於 outage。
	// gateway-internal only，never HTTP-facing.
	// PersistWebSession 是 MINT：登入時建立這個 token 的 row。
	PersistWebSession(context.Context, *connect.Request[account.PersistWebSessionRequest]) (*connect.Response[account.PersistWebSessionResponse], error)
	// TouchWebSession 是 SLIDE：只延長「已存在」的 row，絕不 INSERT。
	// row 不在 = 該 session 已被撤銷（登出／軟刪／停權），呼叫端必須停止承認它。
	TouchWebSession(context.Context, *connect.Request[account.TouchWebSessionRequest]) (*connect.Response[account.TouchWebSessionResponse], error)
	GetWebSession(context.Context, *connect.Request[account.GetWebSessionRequest]) (*connect.Response[account.GetWebSessionResponse], error)
	DeleteWebSession(context.Context, *connect.Request[account.DeleteWebSessionRequest]) (*connect.Response[account.DeleteWebSessionResponse], error)
	// ==================== 憑證撤銷（stateless JWT，#2035） ====================
	//
	// web session 的撤銷＝刪 web_sessions row（上面那組 RPC）。mobile / admin 的
	// Bearer JWT 沒有任何伺服器端紀錄可刪，所以撤銷必須自己有一張表：
	// RevokeToken 撤一枚（登出），RevokeAllCredentials 推進帳號的 auth_epoch
	// 讓它之前簽出的全部作廢（登出全部裝置、角色移除、事故救援）。
	// CheckCredential 是 gateway 在 Redis 答不出來時的重建路徑——與
	// #2050 的 blacklist 重建同一個形狀，且同樣 fail-open。
	RevokeToken(context.Context, *connect.Request[account.RevokeTokenRequest]) (*connect.Response[account.RevokeTokenResponse], error)
	RevokeAllCredentials(context.Context, *connect.Request[account.RevokeAllCredentialsRequest]) (*connect.Response[account.RevokeAllCredentialsResponse], error)
	CheckCredential(context.Context, *connect.Request[account.CheckCredentialRequest]) (*connect.Response[account.CheckCredentialResponse], error)
	// ========== Admin: Account Statistics ==========
	GetAccountStatsForAdmin(context.Context, *connect.Request[account.GetAccountStatsForAdminRequest]) (*connect.Response[account.GetAccountStatsForAdminResponse], error)
}

